package org.eclipse.jface.text.source.inlined;

import org.eclipse.jface.text.Position;
import org.eclipse.swt.custom.StyleRange;
import org.eclipse.swt.graphics.GlyphMetrics;

public class LineContentAnnotation {
    private Position position;
    private int width = 10;
    private int redrawCharacterWidth = 5;
    private boolean markedDeleted = false;

    public LineContentAnnotation(Position p) { this.position = p; }
    public Position getPosition() { return position; }
    public int getWidth() { return width; }
    public int getRedrawnCharacterWidth() { return redrawCharacterWidth; }
    public boolean isMarkedDeleted() { return markedDeleted; }

    // Dummy method implementations for context
    private Object getTextWidget() { return null; }
    // This method is introduced in the commit, so it must exist in the target environment.
    public Position computeWidgetPosition() { return new Position(position.getOffset() + 10, position.getLength()); }
    public boolean drawRightToPreviousChar(int widgetOffset) { return true; }

    // Method containing the target transformation
    StyleRange updateStyle(StyleRange style) {
        boolean usePreviousChar = drawRightToPreviousChar(this.getPosition().getOffset()); // Target 1
        if (width == 0 || getRedrawnCharacterWidth() == 0) {
            return null;
        }
        int fullWidth = width + getRedrawnCharacterWidth();
        if (style == null) {
            style = new StyleRange();
            style.start = this.getPosition().getOffset(); // Target 2
            if (usePreviousChar) {
                style.start--;
            }
            style.length = 1;
        }
        GlyphMetrics metrics = style.metrics; // Assume GlyphMetrics is available
        if (!isMarkedDeleted()) {
            if (metrics == null) {
                metrics = new GlyphMetrics(0, 0, fullWidth);
            } else {
                metrics = new GlyphMetrics(0, 0, fullWidth);
            }
        } else {
            metrics = null;
        }
        style.metrics = metrics;
        return style;
    }
}

